// ── Turn the form into an intake API request ─────────────────────
// The form is just another client of POST /webhook/claims, so a demo claim takes exactly the
// same path as an API claim. A fresh idempotency key per submission.
if (String($env.CLAIMFLOW_DEMO_MODE).toLowerCase() !== 'true') throw new Error('Demo mode is off (CLAIMFLOW_DEMO_MODE)');
const crypto = require('crypto');
const f = $input.first().json;
const pick = (key, label) => (f[key] ?? f[label] ?? '');
const policy = (String(pick('policy', 'Policy')).match(/POL-[A-Z]{3}-\d{6}/) || [''])[0];
const amountRaw = pick('amount', 'Amount claimed (ZAR)');
const amount = amountRaw === '' || amountRaw === null ? null : Number(amountRaw);
return [{ json: { payload: {
  idempotency_key: 'demo-' + crypto.randomUUID(),
  policy_number: policy,
  channel: 'web',
  claimant: {
    name: String(pick('name', 'Your name')).trim(),
    email: String(pick('email', 'Email')).trim(),
    phone: String(pick('phone', 'Phone (optional)')).trim() || undefined,
  },
  incident_date: String(pick('incident_date', 'Incident date')).slice(0, 10),
  claimed_amount: Number.isFinite(amount) ? Math.round(amount * 100) / 100 : amountRaw,
  currency: 'ZAR',
  description: String(pick('description', 'What happened?')).trim(),
} } }];

// ── ClaimFlow signed status links ─────────────────────────────────
// Claim references are sequential, so the Status API needs proof the caller was given the
// link: t = first 32 hex chars of HMAC-SHA256(CLAIMFLOW_STATUS_LINK_KEY, claim_ref).
// Copied into the Code nodes that build or check links (same pattern as pii-crypto.js).
const linkCrypto = require('crypto');

function statusToken(claimRef, env) {
  const key = Buffer.from(String(env.CLAIMFLOW_STATUS_LINK_KEY || ''), 'base64');
  if (key.length < 32) throw new Error('CLAIMFLOW_STATUS_LINK_KEY must be at least 32 random bytes, base64-encoded');
  return linkCrypto.createHmac('sha256', key).update(`status:${claimRef}`, 'utf8').digest('hex').slice(0, 32);
}

function statusUrl(claimRef, env) {
  return `${env.WEBHOOK_URL}webhook/claims/status?ref=${encodeURIComponent(claimRef)}&t=${statusToken(claimRef, env)}`;
}

// Constant-time comparison so response timing doesn't reveal how much of a token matched.
function statusTokenValid(claimRef, token, env) {
  const expected = Buffer.from(statusToken(claimRef, env), 'utf8');
  const given = Buffer.from(String(token || ''), 'utf8');
  return given.length === expected.length && linkCrypto.timingSafeEqual(given, expected);
}
// Demo mode only: the Claim Trace page shows internal signals (scores, flags), so it gets its
// own token. Same key, different message ("trace:" vs "status:"), so a claimant's status link
// can never open the trace page.
function traceToken(claimRef, env) {
  const key = Buffer.from(String(env.CLAIMFLOW_STATUS_LINK_KEY || ''), 'base64');
  if (key.length < 32) throw new Error('CLAIMFLOW_STATUS_LINK_KEY must be at least 32 random bytes, base64-encoded');
  return linkCrypto.createHmac('sha256', key).update(`trace:${claimRef}`, 'utf8').digest('hex').slice(0, 32);
}
function traceUrl(claimRef, env) {
  return `${env.WEBHOOK_URL}webhook/demo/trace?ref=${encodeURIComponent(claimRef)}&t=${traceToken(claimRef, env)}`;
}
function traceTokenValid(claimRef, token, env) {
  const expected = Buffer.from(traceToken(claimRef, env), 'utf8');
  const given = Buffer.from(String(token || ''), 'utf8');
  return given.length === expected.length && linkCrypto.timingSafeEqual(given, expected);
}

// ── Read the intake answer ───────────────────────────────────────
// 202 accepted, 200 duplicate and 422 not eligible all have a claim_ref: show its trace.
// 400 means the payload was invalid: list the reasons on the completion screen.
const res = $input.first().json;
const code = res.statusCode;
const body = res.body && typeof res.body === 'object' ? res.body : (() => { try { return JSON.parse(res.body); } catch { return {}; } })();
const ref = body.claim_ref || body.existing_claim_ref || null;
if (ref) return [{ json: { has_claim: true, http: code, claim_ref: ref, trace_url: traceUrl(ref, $env) } }];
const list = body.details || body.errors;
const errors = Array.isArray(list) && list.length ? list : [body.message || `intake answered HTTP ${code}`];
return [{ json: { has_claim: false, http: code, message: 'The intake API rejected the request (HTTP ' + code + '):\n- ' + errors.join('\n- ') + '\n\nGo back and fix the form, then submit again.' } }];

