  const given = Buffer.from(String(token || ''), 'utf8');
  return given.length === expected.length && linkCrypto.timingSafeEqual(given, expected);
}

// ── Render the Claim Trace page ──────────────────────────────────
// INTERNAL view (demo mode only): shows scores, flags and reviewer notes, which the claimant's
// Status API deliberately hides. Personal details are decrypted only to be shown masked.
const r = $input.first().json;
if (!r.claim_ref) return [{ json: { found: false } }];

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
const money = (n) => (n === null || n === undefined ? 'n/a' : 'R ' + Number(n).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ' '));
const sast = (v) => (v ? DateTime.fromJSDate(new Date(v)).setZone('Africa/Johannesburg') : null);
const HARD = ['prompt_injection_pattern', 'injection_detector'];
const events = r.events || [];
const ev = (type) => events.filter((e) => e.type === type);
const first = (type) => ev(type)[0];
const aiEv = first('ai_analysed')?.detail || {};
const routedEv = first('routed')?.detail || {};
const flags = r.rule_flags || [];
const status = r.status;

// ── masked personal details (proves they're encrypted at rest) ──
let maskedName = '[could not decrypt]', maskedEmail = '[could not decrypt]';
try {
  const keys = piiKeys($env);
  const name = decryptField(r.claimant_name_enc, 'name', keys) || '';
  const email = decryptField(r.claimant_email_enc, 'email', keys) || '';
  maskedName = name.split(/\s+/).map((w) => w.slice(0, 1) + '*'.repeat(Math.max(1, w.length - 1))).join(' ');
  const [u, d] = email.split('@');
  maskedEmail = (u || '').slice(0, 1) + '***@' + (d || '');
} catch (err) { /* shown as could not decrypt */ }
const cipherPreview = String(r.claimant_name_enc || '').slice(0, 28) + '…';

// ── labels ──
const STATUS = {
  received: ['Received', 'info'], rejected_ineligible: ['Rejected: not eligible', 'high'],
  in_standard_queue: ['In the standard queue', 'info'], pending_fraud_review: ['Waiting for fraud review', 'medium'],
  pending_manual_review: ['Waiting for manual triage', 'medium'], approved_for_assessment: ['Approved for assessment', 'low'],
  more_info_required: ['More information requested', 'medium'], rejected: ['Rejected after review', 'high'], closed: ['Closed', 'info'],
};
const ROUTE = {
  fast_track: 'Fast track', standard: 'Standard queue', fraud_review: 'Fraud review',
  manual_review: 'Manual review', rejected: 'Rejected at eligibility',
};
const [statusLabel, statusTone] = STATUS[status] || [status, 'info'];
const tone = (score) => (score === null || score === undefined ? 'info' : score >= 60 ? 'high' : score >= 25 ? 'medium' : 'low');

// ── is anything still happening? then the page refreshes itself ──
const ageSec = (Date.now() - new Date(r.reported_at).getTime()) / 1000;
const notified = ev('notification_sent').length > 0;
const live = status === 'received' || status === 'pending_fraud_review' || (!notified && ageSec < 90);

// ── pipeline steps ──
const steps = [];
const step = (title, state, note) => steps.push({ title, state, note });
step('Received', 'done', 'validated, PII encrypted, stored');
if (status === 'rejected_ineligible' || r.route === 'rejected') {
  step('Eligibility', 'fail', (r.rejection_reasons || []).join(', ') || 'not eligible');
  step('AI analysis', 'skip', 'not needed: rejected before analysis');
  step('Rules and route', 'skip', '');
} else {
  step('Eligibility', 'done', `policy ${r.policy_status || 'active'}, within cover`);
  const inj = aiEv.injection_check || {};
  const tripwire = flags.some((f) => f.code === 'prompt_injection_pattern');
  step('Injection check', inj.failed ? 'warn' : (inj.flagged || tripwire) ? 'fail' : 'done',
    inj.failed ? 'detector unavailable: no fast track' : inj.flagged ? `detector flagged (confidence ${inj.confidence})` : tripwire ? 'regex tripwire fired' : `clear${inj.confidence !== null && inj.confidence !== undefined ? ' (confidence ' + inj.confidence + ')' : ''}`);
  step('AI analysis', r.ai_status === 'ok' ? 'done' : 'fail', r.ai_status === 'ok' ? `${r.ai_model} · AI risk ${r.ai_risk_score}` : `failed: ${(aiEv.problems || []).join('; ') || 'no valid output'}`);
  step('Rules and score', flags.length ? 'warn' : 'done', `${flags.length} flag${flags.length === 1 ? '' : 's'} · final risk ${r.final_risk_score}`);
  step('Route', r.route === 'fraud_review' || r.route === 'manual_review' ? 'warn' : 'done', ROUTE[r.route] || r.route || '');
}
step('Claimant emailed', notified ? 'done' : 'wait', notified ? ev('notification_sent').map((e) => e.detail.template).join(', ') : 'sending…');
if (r.route === 'fraud_review') {
  const decided = first('review_decision');
  const timedOut = first('review_timed_out');
  step('Human review', decided ? 'done' : timedOut ? 'warn' : 'wait',
    decided ? `${decided.detail.decision} by ${decided.actor}` : timedOut ? 'timed out: back to the queue' : 'waiting for the fraud team (see Mailpit)');
}
const ICON = { done: '✓', warn: '!', fail: '✕', wait: '…', skip: '–' };
const stepsHtml = steps.map((s) => `<li class="step ${s.state}"><span class="dot">${ICON[s.state]}</span><div><b>${esc(s.title)}</b><small>${esc(s.note)}</small></div></li>`).join('');

// ── panels ──
const facts = (rows) => `<table class="facts">${rows.map(([k, v, raw]) => `<tr><th>${esc(k)}</th><td>${raw ? v : esc(v)}</td></tr>`).join('')}</table>`;
const chips = (items, cls = '') => (items.length ? items.map((i) => `<span class="chip ${cls}">${esc(i)}</span>`).join(' ') : '<span class="muted">none</span>');
const bar = (score) => `<div class="bar"><span class="${tone(score)}" style="width:${Math.max(2, Math.min(100, score || 0))}%"></span></div>`;

const claimPanel = facts([
  ['Policy', `${r.submitted_policy_number}${r.product ? ' · ' + r.product : ' · not found'}`],
  ['Cover', r.sum_insured ? `${money(r.sum_insured)} (since ${r.policy_start})` : 'n/a'],
  ['Amount claimed', money(r.claimed_amount)],
  ['Incident date', r.incident_date],
  ['Submitted', sast(r.reported_at)?.toFormat('d LLL yyyy, HH:mm:ss') + ' SAST'],
  ['Channel', r.channel],
]) + `<p class="label">Description (shown as plain text, never executed)</p><blockquote>${esc(r.description)}</blockquote>`;

const piiPanel = facts([
  ['Name', maskedName],
  ['Email', maskedEmail],
  ['Stored in the database as', `<code>${esc(cipherPreview)}</code>`, true],
  ['Email lookup key', `<code>${esc(String(r.claimant_email_hmac || '').slice(0, 16))}…</code> (HMAC)`, true],
]) + '<p class="muted">AES-256-GCM per field. The AI never receives these.</p>';

let aiPanel;
if (status === 'rejected_ineligible') {
  aiPanel = '<p class="muted">Not run: the claim was rejected at eligibility, before any AI call.</p>';
} else if (r.ai_status !== 'ok') {
  aiPanel = `<p><span class="pill high">AI analysis failed</span></p><p>${esc((aiEv.problems || []).join('; ') || 'no valid output')}</p><p class="muted">The pipeline doesn't guess: this claim goes to a human (manual review).</p>`;
} else {
  const inj = aiEv.injection_check || {};
  aiPanel = facts([
    ['Model', `${r.ai_model} (${aiEv.mode || 'n/a'})`],
    ['AI risk score', `<b>${r.ai_risk_score}</b> / 100 ${bar(r.ai_risk_score)}`, true],
    ['Claim type · severity', `${r.ai_claim_type} · ${r.ai_severity}`],
    ['Injection detector', inj.failed ? 'unavailable' : `${inj.flagged ? 'FLAGGED' : 'clear'} (confidence ${inj.confidence ?? 'n/a'})`],
  ]) + `<p class="label">Summary</p><p>${esc(r.ai_summary)}</p>
<p class="label">Fraud indicators</p><p>${chips(r.ai_fraud_indicators || [], 'medium')}</p>
<p class="label">Missing information</p><p>${chips(r.ai_missing_information || [])}</p>${(aiEv.warnings || []).length ? `<p class="muted">Output warnings: ${esc(aiEv.warnings.join('; '))}</p>` : ''}<p class="muted">Advisory only: the AI never decides the route.</p>`;
}

let rulesPanel;
if (status === 'rejected_ineligible') {
  rulesPanel = `<p>Eligibility rules rejected it:</p><p>${chips(r.rejection_reasons || [], 'high')}</p>`;
} else {
  const rows = flags.map((f) => `<tr class="${HARD.includes(f.code) ? 'hard' : ''}"><td><code>${esc(f.code)}</code>${HARD.includes(f.code) ? ' <span class="pill high">hard flag</span>' : ''}</td><td class="num">+${f.points}</td><td>${esc(f.detail)}</td></tr>`).join('');
  const blend = r.ai_status === 'ok'
    ? `0.6 × AI ${r.ai_risk_score} + 0.4 × rules ${r.rule_score} = <b>${r.final_risk_score}</b>`
    : `AI failed, so final = rule score = <b>${r.final_risk_score}</b>`;
  rulesPanel = (flags.length ? `<table class="flags"><tr><th>Flag</th><th>Points</th><th>Why</th></tr>${rows}</table>` : '<p class="muted">No rule flags fired.</p>')
    + facts([
      ['Rule score', `${r.rule_score} / 100`],
      ['Final risk', `${blend} ${bar(r.final_risk_score)}`, true],
      ['Route', `<b>${esc(ROUTE[r.route] || r.route)}</b>`, true],
      ['Why this route', (routedEv.route_reasons || []).join('; ')],
    ]);
}

let reviewPanel = '';
if (r.route === 'fraud_review') {
  const decided = first('review_decision');
  reviewPanel = decided
    ? facts([['Decision', decided.detail.decision], ['Reviewer', r.reviewer || decided.actor], ['Internal notes', r.reviewer_notes || '(none)'], ['Decided', sast(r.reviewed_at)?.toFormat('HH:mm:ss') + ' SAST']])
    : `<p><span class="pill medium">Waiting for the fraud team</span></p><p>Open the <b>[Fraud review] ${esc(r.claim_ref)}</b> email in <a href="${esc($env.CLAIMFLOW_MAILPIT_URL)}" target="_blank">Mailpit</a>, click <b>Review this claim</b> and decide. This page updates by itself.</p>`;
}

const t0 = events.length ? new Date(events[0].at).getTime() : 0;
const timeline = events.map((e) => {
  const d = { ...e.detail };
  return `<tr><td class="num">${sast(e.at).toFormat('HH:mm:ss')}</td><td class="num muted">+${((new Date(e.at).getTime() - t0) / 1000).toFixed(1)}s</td><td><b>${esc(e.type)}</b></td><td>${esc(e.actor)}</td><td><code>${esc(JSON.stringify(d))}</code></td></tr>`;
}).join('');

const base = $env.WEBHOOK_URL;
const html = `<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
${live ? '<meta http-equiv="refresh" content="3">' : ''}<title>${esc(r.claim_ref)} · ClaimFlow trace</title>
