.big{font-size:16px;padding:4px 14px}.live{color:var(--muted);font-size:12px}
.steps{list-style:none;display:flex;flex-wrap:wrap;gap:8px;padding:0;margin:0 0 18px}
.step{flex:1 1 140px;display:flex;gap:8px;background:#fff;border:1px solid var(--line);border-radius:8px;padding:10px}
.step small{display:block;color:var(--muted);font-size:12px}
.dot{flex:none;width:24px;height:24px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:700;color:#fff;background:#9aa5b1}
.done .dot{background:var(--low)}.warn .dot{background:var(--medium)}.fail .dot{background:var(--high)}.wait .dot{background:var(--info);animation:pulse 1.2s infinite}
@keyframes pulse{50%{opacity:.35}}
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(340px,1fr));gap:16px}
section{background:#fff;border:1px solid var(--line);border-radius:8px;padding:14px 16px}
section h2{margin:0 0 10px;font-size:13px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
.wide{grid-column:1/-1}
table{border-collapse:collapse;width:100%}th,td{text-align:left;vertical-align:top;padding:6px 8px 6px 0;border-bottom:1px solid var(--line);font-size:13px}
.facts th{width:38%;color:var(--muted);font-weight:normal}.flags th,.trace th{color:var(--muted);font-weight:600}
tr.hard td{background:var(--high-bg)}.num{white-space:nowrap;font-variant-numeric:tabular-nums}
code{font:12px Consolas,monospace;background:var(--panel);padding:1px 4px;border-radius:3px;word-break:break-all}
blockquote{margin:0;border-left:3px solid #9aa5b1;background:var(--panel);padding:8px 12px;white-space:pre-wrap;font-style:italic}
.label{margin:10px 0 2px;font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
.muted{color:var(--muted);font-size:12px}
.chip{display:inline-block;background:var(--info-bg);color:var(--info);border-radius:12px;padding:1px 9px;font-size:12px;margin:2px 0}
.chip.medium{background:var(--medium-bg);color:var(--medium)}.chip.high{background:var(--high-bg);color:var(--high)}
.bar{height:6px;background:var(--line);border-radius:3px;margin-top:4px}.bar span{display:block;height:6px;border-radius:3px}
.bar .high{background:var(--high)}.bar .medium{background:var(--medium)}.bar .low{background:var(--low)}.bar .info{background:var(--info)}
nav{display:flex;flex-wrap:wrap;gap:10px;margin:18px 0 4px}
nav a{background:#fff;border:1px solid var(--line);border-radius:6px;padding:8px 12px;color:var(--brand);text-decoration:none;font-weight:600}
nav a.primary{background:var(--brand);color:#fff;border-color:var(--brand)}
</style></head><body>
<header><h1>Claim trace · ${esc(r.claim_ref)}</h1><p>Acme Cover · ClaimFlow pipeline, internal view</p></header>
<main>
<div class="demo"><b>Demo mode.</b> This page shows internal signals (risk scores, rule flags, reviewer notes). The claimant never sees them: compare <a href="${esc(statusUrl(r.claim_ref, $env))}" target="_blank">what the claimant sees</a>.</div>
<div class="hero"><span class="pill big ${statusTone}">${esc(statusLabel)}</span>
${r.route ? `<span class="pill big info">Route: ${esc(ROUTE[r.route] || r.route)}</span>` : ''}
${r.final_risk_score !== null && r.final_risk_score !== undefined ? `<span class="pill big ${tone(r.final_risk_score)}">Final risk ${r.final_risk_score}</span>` : ''}
<span class="live">${live ? '● live: refreshing every 3 s' : 'Last updated ' + esc(sast(r.updated_at)?.toFormat('HH:mm:ss')) + ' SAST'}</span></div>
<ol class="steps">${stepsHtml}</ol>
<div class="grid">
<section><h2>The claim</h2>${claimPanel}</section>
<section><h2>AI analysis</h2>${aiPanel}</section>
<section><h2>Rules, score and route</h2>${rulesPanel}</section>
${reviewPanel ? `<section><h2>Human review</h2>${reviewPanel}</section>` : ''}
<section><h2>Personal data protection</h2>${piiPanel}</section>
<section class="wide"><h2>Audit trail (claim_events, append-only)</h2><table class="trace"><tr><th>Time</th><th></th><th>Event</th><th>Actor</th><th>Detail</th></tr>${timeline}</table></section>
</div>
<nav><a class="primary" href="${esc(base)}form/claim-demo">Log another claim</a>
<a href="${esc($env.CLAIMFLOW_MAILPIT_URL)}" target="_blank">Emails (Mailpit)</a>
<a href="${esc(statusUrl(r.claim_ref, $env))}" target="_blank">Claimant's Status API view</a>
<a href="${esc($env.N8N_EDITOR_BASE_URL || base)}workflow/pY62sSjeshgn8nDx/executions" target="_blank">Node by node in n8n (Executions)</a></nav>
</main></body></html>`;
